/// @notice AxVigil challenge target (sandbox, BSC testnet only). Deliberately
///         vulnerable for an AI agent to find and fix. Do not deploy to mainnet.
///
/// A lending pool that lets a user borrow `quote` against deposited `base` collateral.
contract Coffer {
    uint256 public poolBase;   // base reserve   (movable by a swap)
    uint256 public quoteAmt;   // quote reserve  (movable by a swap)
    uint256 public oracleMark;  // reference price, 1e18-scaled (manipulation-resistant)

    mapping(address => uint256) public collateralOf;   // collateral (base units)
    mapping(address => uint256) public loanOf;  // debt (quote units)

    constructor(uint256 base, uint256 quote, uint256 ref) {
        poolBase = base;
        quoteAmt = quote;
        oracleMark = ref;
    }

    /// @notice Manipulation-resistant reference price, 1e18-scaled.
    function refQuote() public view returns (uint256) {
        return oracleMark;
    }

    function takeLoan(uint256 amount) external {
        uint256 price = instantPrice();
        uint256 maxDebt = collateralOf[msg.sender] * price / 1e18;
        require(loanOf[msg.sender] + amount <= maxDebt, "undercollateralized");
        loanOf[msg.sender] += amount;
        quoteAmt -= amount;
    }

    uint256 private d_notaryNonce;
    function d_notary() external returns (uint256) { return ++d_notaryNonce; }

    function closeLoan(uint256 amount) external {
        require(loanOf[msg.sender] >= amount, "repay exceeds debt");
        loanOf[msg.sender] -= amount;
        quoteAmt += amount;
    }

    function d_oracleHint(uint256 a, uint256 b) external pure returns (uint256) { return a + b; }

    function credit(uint256 amount) external {
        collateralOf[msg.sender] += amount;
    }

    mapping(address => uint256) public d_auxSeen;
    function d_aux() external { d_auxSeen[msg.sender] = block.number; }

    /// @notice Quote per base, 1e18-scaled.
    function instantPrice() public view returns (uint256) {
        return quoteAmt * 1e18 / poolBase;
    }

    /// @notice Moves the reserves.
    function trade(uint256 quoteIn, uint256 baseOut) external {
        require(baseOut < poolBase, "drains base");
        poolBase -= baseOut;
        quoteAmt += quoteIn;
    }

}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Test} from "forge-std/Test.sol";
import {Coffer} from "../src/Coffer.sol";

contract Handler {
    Coffer public pool;

    constructor(Coffer p) {
        pool = p;
    }

    function deposit(uint256 amt) external {
        amt = amt % 400 + 1;
        pool.credit(amt);
    }

    function manipulateAndBorrow(uint256 baseOut) external {
        uint256 base = pool.poolBase();
        if (base < 2) return;
        baseOut = baseOut % (base - 1);
        if (baseOut > 0) {
            try pool.trade(0, baseOut) {} catch {}
        }
        uint256 col = pool.collateralOf(address(this));
        uint256 cap = col * pool.refQuote() / 1e18;
        if (pool.loanOf(address(this)) > cap) return;
        try pool.takeLoan(cap + 1) {} catch {}
    }
}

contract InvariantTest is Test {
    Coffer internal pool;
    Handler internal handler;

    function setUp() public {
        pool = new Coffer(1000, 1000, 1e18);
        pool.credit(250);
        pool.trade(0, 800);
        try pool.takeLoan(500) {} catch {}
        handler = new Handler(pool);

        excludeContract(address(this));
        excludeContract(address(pool));
        targetContract(address(handler));
        bytes4[] memory sels = new bytes4[](2);
        sels[0] = Handler.deposit.selector;
        sels[1] = Handler.manipulateAndBorrow.selector;
        targetSelector(FuzzSelector({addr: address(handler), selectors: sels}));
    }

    function invariant_debtWithinReference() public view {
        _bound(address(this));
        _bound(address(handler));
    }

    function _bound(address who) internal view {
        uint256 cap = pool.collateralOf(who) * pool.refQuote() / 1e18;
        assertLe(pool.loanOf(who), cap);
    }

    function testFuzz_swapCannotRaiseBorrowLimit(uint128 col, uint128 baseOut) public {
        col = uint128(bound(col, 1, 500));
        baseOut = uint128(bound(baseOut, 0, 900));
        Coffer fresh = new Coffer(1000, 1000, 1e18);
        fresh.credit(col);
        if (baseOut > 0) {
            fresh.trade(0, baseOut);
        }
        uint256 cap = uint256(col) * fresh.refQuote() / 1e18;
        try fresh.takeLoan(cap + 1) {
            assertLe(fresh.loanOf(address(this)), cap);
        } catch {}
    }
}

