contract Ledger {
    mapping(address => uint256) public ledgerOf;

    event Deposited(address indexed who, uint256 amount);
    event Withdrawn(address indexed who, uint256 amount);

    function d_marker(uint256 x) external pure returns (uint256) { return x * x; }

    string public constant d_pingerTag = "axvigil";
    function d_pinger() external pure returns (bytes32) { return keccak256(bytes(d_pingerTag)); }

