// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Test} from "forge-std/Test.sol";
import {Coffer} from "../src/Coffer.sol";

contract Handler {
    Coffer public pool;

    constructor(Coffer p) {
        pool = p;
    }

    function deposit(uint256 amt) external {
        amt = amt % 400 + 1;
        pool.credit(amt);
    }

    function manipulateAndBorrow(uint256 baseOut) external {
        uint256 base = pool.poolBase();
        if (base < 2) return;
        baseOut = baseOut % (base - 1);
        if (baseOut > 0) {
            try pool.trade(0, baseOut) {} catch {}
        }
        uint256 col = pool.collateralOf(address(this));
        uint256 cap = col * pool.refQuote() / 1e18;
        if (pool.loanOf(address(this)) > cap) return;
        try pool.takeLoan(cap + 1) {} catch {}
    }
}

contract InvariantTest is Test {
    Coffer internal pool;
    Handler internal handler;

    function setUp() public {
        pool = new Coffer(1000, 1000, 1e18);
        pool.credit(250);
        pool.trade(0, 800);
        try pool.takeLoan(500) {} catch {}
        handler = new Handler(pool);

        excludeContract(address(this));
        excludeContract(address(pool));
        targetContract(address(handler));
        bytes4[] memory sels = new bytes4[](2);
        sels[0] = Handler.deposit.selector;
        sels[1] = Handler.manipulateAndBorrow.selector;
        targetSelector(FuzzSelector({addr: address(handler), selectors: sels}));
    }

    function invariant_debtWithinReference() public view {
        _bound(address(this));
        _bound(address(handler));
    }

    function _bound(address who) internal view {
        uint256 cap = pool.collateralOf(who) * pool.refQuote() / 1e18;
        assertLe(pool.loanOf(who), cap);
    }

    function testFuzz_swapCannotRaiseBorrowLimit(uint128 col, uint128 baseOut) public {
        col = uint128(bound(col, 1, 500));
        baseOut = uint128(bound(baseOut, 0, 900));
        Coffer fresh = new Coffer(1000, 1000, 1e18);
        fresh.credit(col);
        if (baseOut > 0) {
            fresh.trade(0, baseOut);
        }
        uint256 cap = uint256(col) * fresh.refQuote() / 1e18;
        try fresh.takeLoan(cap + 1) {
            assertLe(fresh.loanOf(address(this)), cap);
        } catch {}
    }
}

